const parts = [...trimmed.matchAll(/(\d+)([dhms])/g)]
const order = 'dhms'
const ok = parts.length > 0 && parts.map((p) => p[0]).join('') === trimmed && parts.every((p, i) => i === 0 || order.indexOf(p[2]) >= order.indexOf(parts[i - 1][2]))
const sums = {}
for (const p of parts) sums[p[2]] = String(Number(sums[p[2]] || 0) + Number(p[1]))
const match = ok ? [trimmed, sums.d, sums.h, sums.m, sums.s] : null
